    {"model": "Qwen2.5-0.5B-Instruct", "reason": "Only Base and Instruct published. No intermediate alignment checkpoints."},
    {"model": "Pythia (base)", "reason": "154 pretraining checkpoints per size, but EleutherAI did not perform alignment. Need third-party aligned variants."}
  ],

  "feasibility_assessment": {
    "recommended_primary": "OLMo-2-0425-1B",
    "why": "1B params = ~4GB fp32, feasible on CPU. 4 alignment stages (Base→SFT→DPO→Instruct). Apache-2.0. Established in literature (Karouzos et al. 2026 used OLMo for diversity collapse analysis).",
    "recommended_secondary": "SmolLM3-3B-checkpoints",
    "cpu_inference_estimate": {
      "OLMo-2-1B_fp32": "~3-5 tokens/sec on modern CPU, ~200 tokens in 40-60 sec per prompt",
      "SmolLM3-3B_int8": "~1-2 tokens/sec on CPU, slower but feasible for small eval sets",
      "generation_budget": "1000 prompts × 4 stages × 200 tokens = 800K tokens. At ~4 tok/s = ~55 hours for OLMo-1B. Recommend subsampling to 100-200 prompts."
