    "gpu_alternative": "If GPU available: run full 1000 prompts in ~2-4 hours total across all stages.",
    "self_train_fallback": "If no satisfactory checkpoints: fine-tune Pythia-410M or SmolLM-135M with TRL DPO on UltraFeedback, save per-epoch checkpoints. Requires 1 GPU, ~2 hours. Recommend Director allocate if needed."
  },

  "experiment_design": {
    "eval_set": "WikiText-103 test, first 200 sentences (subsampled for CPU budget)",
    "generation_config": {
      "max_new_tokens": 200,
      "temperature": 1.0,
      "top_p": 0.95,
      "do_sample": true,
      "num_return_sequences": 5,
      "note": "T=1.0 to preserve natural diversity signal; 5 continuations per prompt for within-prompt diversity"
    },
    "checkpoints_to_evaluate": [
      "allenai/OLMo-2-0425-1B (Base)",
      "allenai/OLMo-2-0425-1B-SFT",
      "allenai/OLMo-2-0425-1B-DPO",
      "allenai/OLMo-2-0425-1B-Instruct"
    ],
    "metrics_per_stage": [
      "token_entropy (H) — Shannon entropy of next-token distribution",
      "distinct_1 / distinct_2 / distinct_3 — ratio of unique n-grams",
      "ECE — expected calibration error",
      "perplexity — on held-out text",
      "repetition_rate — fraction of repeated 4-grams in generations",
      "self_BLEU — intra-prompt generation similarity"
    ],
    "permg_application": {
      "concept": "Treat each alignment stage as a 'generation' in the PermG framework. The 4-stage sequence (Base→SFT→DPO→Instruct) is analogous to the multi-generation autoregressive degradation studied in the paper.",
      "analysis": [
        "Compute per-metric trajectories across 4 stages",
        "Run cross-correlation between entropy and distinct-n trajectories",
        "Test for lead-lag: does entropy decline precede distinct-n decline?",
        "Compute PermG K-value: how many stages until collapse threshold?"
      ],
      "limitation": "Only 4 stages (not the 10-20 generations in standard PermG). Statistical power is limited. Mitigate by: (1) using per-prompt metrics as repeated measures, (2) adding SmolLM3 as replication, (3) if RLVR step-level checkpoints give 10+ points, use those for finer-grained analysis."
    }
  },

  "literature_support": {
    "diversity_collapse_established": true,
    "key_papers": [
      {
        "citation": "Kirk et al. (2024). Understanding the Effects of RLHF on LLM Generalisation and Diversity. ICLR 2024.",
        "arxiv": "2310.06452",
        "finding": "RLHF significantly reduces output diversity (syntactic, semantic, logical). Across-input mode collapse confirmed. Not explained by reward model alone (BoN maintains diversity).",
        "code": "github.com/facebookresearch/rlfh-gen-div"
      },
      {
        "citation": "Karouzos et al. (2026). Where does output diversity collapse in post-training? arXiv:2604.16027.",
        "arxiv": "2604.16027",
        "finding": "Diversity collapse location is pipeline-dependent: SFT for some lineages, DPO for others. Used OLMo checkpoints. Suppressing CoT does not recover diversity.",
        "code": "github.com/ckarouzos/where-diversity-collapses"
      },
      {
        "citation": "Guo et al. (2025). Diverse Preference Optimization (DivPO). arXiv:2501.18101.",
        "arxiv": "2501.18101",
        "finding": "Standard DPO objective is inherently diversity-destroying: shifting all probability to one high-reward response is optimal under the loss. DivPO achieves 45-75% diversity recovery."
      },
      {
        "citation": "Lin et al. (2024). Mitigating the Alignment Tax of RLHF. EMNLP 2024.",
        "finding": "Alignment tax = diversity + fluency drop. DPO induces less tax than PPO."
      },
      {
        "citation": "Tomihari (2026). Learning Dynamics in RL Post-Training for Language Models. arXiv:2601.04670.",
        "arxiv": "2601.04670",
        "finding": "Entropy decreases monotonically during RL post-training (NTK analysis). Limited feature variability causes systematic confidence increase."
      },
      {
        "citation": "Li et al. (2025). Rediscovering Entropy Regularization. arXiv:2510.10959.",
        "arxiv": "2510.10959",
        "finding": "RLVR training suffers policy entropy collapse. Fixed entropy coefficients are unstable."
      }
    ],
    "theoretical_prediction": "Entropy decline should lead distinct-n decline in alignment pipeline, because: (1) DPO/RLHF directly optimizes log-probability ratios, compressing the output distribution first (entropy drops), (2) n-gram diversity is a downstream consequence of distribution concentration (distinct-n drops after), (3) This mirrors the token_entropy → distinct lead-lag observed in autoregressive model collapse."
  }
}

